"""Storage layer: data-directory catalog, CSV loading and column type inference."""
from __future__ import annotations

import csv
import os
import re
from dataclasses import dataclass
from typing import List, Optional

from .errors import DataIOError

_INT_RE = re.compile(r"[+-]?[0-9]+")
_REAL_RE = re.compile(r"[+-]?([0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)([eE][+-]?[0-9]+)?")


@dataclass
class Table:
    stem: str
    file_name: str
    columns: List[str]
    types: List[str]
    rows: List[tuple]


class Catalog:
    def __init__(self, data_dir):
        self.path = os.fspath(data_dir)
        self.display = str(self.path)
        if not os.path.isdir(self.path):
            raise DataIOError("data directory not found: %s" % self.display)

    def _scan(self):
        """Fresh scan: list of (stem, path) for regular *.csv files."""
        try:
            with os.scandir(self.path) as it:
                return [
                    (e.name[:-4], e.path)
                    for e in it
                    if e.name.lower().endswith(".csv") and e.is_file()
                ]
        except (FileNotFoundError, NotADirectoryError):
            raise DataIOError("data directory not found: %s" % self.display) from None
        except OSError as exc:
            raise DataIOError(exc.strerror or str(exc)) from None

    def table_names(self) -> List[str]:
        return sorted((stem for stem, _ in self._scan()), key=lambda s: (s.lower(), s))

    def resolve(self, name: str) -> Optional[str]:
        key = name.lower()
        matches = [path for stem, path in self._scan() if stem.lower() == key]
        if len(matches) > 1:
            raise DataIOError("ambiguous table file '%s'" % name)
        return matches[0] if matches else None

    def load(self, name: str) -> Optional[Table]:
        path = self.resolve(name)
        return None if path is None else read_table(path)


def _infer(values):
    """(type, converted values) for one column of raw fields."""
    present = [v for v in values if v != ""]
    if not present:
        return "TEXT", [None] * len(values)
    if all(_INT_RE.fullmatch(v) for v in present):
        conv, kind = int, "INTEGER"
    elif all(_REAL_RE.fullmatch(v) for v in present):
        conv, kind = float, "REAL"
    else:
        conv, kind = str, "TEXT"
    return kind, [None if v == "" else conv(v) for v in values]


def read_table(path: str) -> Table:
    file_name = os.path.basename(path)
    stem = file_name[:-4]

    def fail(msg):
        return DataIOError("%s: %s" % (file_name, msg))

    header = None
    records = []
    reader = None
    try:
        with open(path, encoding="utf-8-sig", newline="") as f:
            reader = csv.reader(f, strict=True)
            for record in reader:
                if not record:
                    continue
                if header is None:
                    seen = set()
                    for col in record:
                        if col == "":
                            raise fail("empty column name")
                        if col.lower() in seen:
                            raise fail("duplicate column '%s'" % col)
                        seen.add(col.lower())
                    header = record
                elif len(record) != len(header):
                    raise fail(
                        "line %d: expected %d fields, got %d"
                        % (reader.line_num, len(header), len(record))
                    )
                else:
                    records.append(record)
    except csv.Error:
        raise fail("line %d: malformed CSV" % reader.line_num) from None
    except UnicodeDecodeError:
        raise fail("invalid UTF-8") from None
    except OSError as exc:
        raise fail(exc.strerror or str(exc)) from None
    if header is None:
        raise fail("empty file")

    types = []
    columns_data = []
    for i in range(len(header)):
        kind, values = _infer([r[i] for r in records])
        types.append(kind)
        columns_data.append(values)
    rows = list(zip(*columns_data)) if records else []
    return Table(stem, file_name, list(header), types, rows)
"""AST nodes produced by minisql.sqlparser (implementation plan section 3.4).

Every node carries `start`/`end` (offset of the first character and one past the last
character of the construct) and `pos` (the offset used for error reporting, spec 5.3).
Names are unescaped (quotes removed); their token offsets are kept in `*_pos` fields.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, List, Optional

# ---- expressions -------------------------------------------------------------------


@dataclass
class Literal:
    kind: str  # 'INTEGER' | 'REAL' | 'TEXT' | 'NULL'
    value: Any  # int | float | str | None
    start: int
    end: int
    pos: int  # the literal token


@dataclass
class ColumnRef:
    qualifier: Optional[str]
    name: str
    qualifier_pos: Optional[int]
    name_pos: int
    start: int
    end: int
    pos: int  # first token (== start)


@dataclass
class Unary:
    op: str  # '-' | '+'
    operand: Any
    start: int
    end: int
    pos: int  # operator token


@dataclass
class Binary:
    op: str  # arithmetic or comparison operator as written
    left: Any
    right: Any
    start: int
    end: int
    pos: int  # operator token


@dataclass
class Logical:
    op: str  # 'AND' | 'OR'
    left: Any
    right: Any
    start: int
    end: int
    pos: int  # operator token


@dataclass
class Not:
    operand: Any
    start: int
    end: int
    pos: int  # NOT token


@dataclass
class IsNull:
    operand: Any
    negated: bool
    start: int
    end: int
    pos: int  # IS token


@dataclass
class Like:
    operand: Any
    pattern: Any
    escape: Optional[Literal]  # TEXT literal or None
    negated: bool
    escape_pos: Optional[int]
    start: int
    end: int
    pos: int  # LIKE token (even when negated)


@dataclass
class InList:
    operand: Any
    items: List[Any]
    negated: bool
    start: int
    end: int
    pos: int  # IN token


@dataclass
class Call:
    name: str  # as written (unescaped if quoted)
    arg: Any  # expression, or None when star
    star: bool
    star_pos: Optional[int]
    start: int
    end: int  # one past ')'
    pos: int  # name token


@dataclass
class Paren:
    expr: Any
    start: int  # '('
    end: int  # one past ')'
    pos: int  # '('


# ---- clauses -----------------------------------------------------------------------


@dataclass
class StarItem:
    start: int
    end: int
    pos: int  # '*'


@dataclass
class QualifiedStarItem:
    qualifier: str
    qualifier_pos: int
    star_pos: int
    start: int
    end: int
    pos: int  # qualifier token


@dataclass
class ExprItem:
    expr: Any
    alias: Optional[str]
    alias_pos: Optional[int]
    start: int  # expression span only (alias excluded): output name = sql[start:end]
    end: int
    pos: int  # expression start


@dataclass
class TableRef:
    name: str
    name_pos: int
    alias: Optional[str]
    alias_pos: Optional[int]
    start: int
    end: int
    pos: int  # name token

    @property
    def range_name(self) -> str:
        return self.name if self.alias is None else self.alias

    @property
    def range_pos(self) -> int:
        return self.name_pos if self.alias is None else self.alias_pos


@dataclass
class Join:
    kind: str  # 'INNER' | 'LEFT'
    table: TableRef
    on: Any
    start: int  # first join keyword
    end: int
    pos: int  # first join keyword


@dataclass
class OrderItem:
    expr: Any
    desc: bool
    start: int
    end: int
    pos: int  # expression start


@dataclass
class Query:
    distinct: bool
    items: List[Any]
    from_table: Optional[TableRef]
    joins: List[Join]
    where: Any
    group_by: List[Any]
    having: Any
    order_by: List[OrderItem]
    limit: Optional[int]
    offset: Optional[int]
    start: int  # SELECT
    end: int  # one past the last consumed token (including ';')
    pos: int  # SELECT
"""Stdlib-only guard: every import in minisql/*.py must be in the allowlist; never sqlite3."""
from __future__ import annotations

import ast
import glob
import os

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

# Explicit stdlib allowlist (do not use sys.stdlib_module_names; Python 3.9 lacks it).
# Tasks listing this file in scope may extend it with stdlib modules only.
STDLIB_ALLOWLIST = frozenset(
    """
    __future__ argparse codecs collections contextlib csv dataclasses decimal enum errno
    functools glob io itertools locale math numbers operator os pathlib re shutil signal
    stat string sys textwrap traceback types typing unicodedata warnings weakref
    """.split()
)


def _module_files():
    files = sorted(glob.glob(os.path.join(REPO_ROOT, "minisql", "*.py")))
    assert files, "no minisql/*.py files found"
    return files


def _imported_top_levels(path):
    with open(path, "rb") as f:
        tree = ast.parse(f.read(), filename=path)
    names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                names.add(alias.name.split(".")[0])
        elif isinstance(node, ast.ImportFrom):
            if node.level:  # relative import: within the package
                continue
            names.add(node.module.split(".")[0])
    return names


def test_only_stdlib_imports():
    bad = {}
    for path in _module_files():
        extra = _imported_top_levels(path) - STDLIB_ALLOWLIST - {"minisql"}
        if extra:
            bad[os.path.basename(path)] = sorted(extra)
    assert bad == {}


def test_no_sqlite3():
    assert "sqlite3" not in STDLIB_ALLOWLIST
    for path in _module_files():
        assert "sqlite3" not in _imported_top_levels(path), path


def test_guard_detects_forbidden_import(tmp_path):
    p = tmp_path / "x.py"
    p.write_text("import sqlite3\nfrom os import path\nfrom . import y\nimport numpy.linalg\n")
    assert _imported_top_levels(str(p)) == {"sqlite3", "os", "numpy"}
